/* Popover, dropdown menu and select content on Radix: a bordered panel above the page. */
.popover { z-index: var(--z-drawer); min-width: 200px; max-width: min(360px, 92vw); padding: var(--s4); background: var(--background); color: var(--foreground); border: 1px solid var(--foreground); box-shadow: var(--shadow-popover); animation: dialog-fade var(--fast) var(--ease); }
.popover:focus-visible { outline-offset: 2px; }
.menu-content { z-index: var(--z-drawer); min-width: 200px; padding: var(--s1) 0; background: var(--background); color: var(--foreground); border: 1px solid var(--foreground); box-shadow: var(--shadow-popover); animation: dialog-fade var(--fast) var(--ease); }
.menu-content .menu-item { cursor: pointer; }
.menu-content .menu-item[data-highlighted] { background: var(--foreground); color: var(--background); outline: none; }
.menu-content .menu-item[data-disabled] { opacity: var(--opacity-disabled); pointer-events: none; }
.menu-content .menu-item[data-variant="danger"][data-highlighted] { background: var(--danger); }
.menu-label { padding: var(--s2) var(--s4); font-size: var(--text-xs); text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); }
.menu-indicator { width: 14px; display: inline-flex; justify-content: center; }
.menu-item-check { display: flex; align-items: center; gap: var(--s3); }

source.content:
'use client';
import {
  createContext,
  forwardRef,
  useContext,
  useRef,
  type AnchorHTMLAttributes,
  type HTMLAttributes,
  type PointerEvent,
  type ReactNode,
  type RefObject,
} from 'react';
import {Slot} from '../../utils/slot';
import {useControllableState} from '../../hooks/use-controllable-state';
import {cx} from '../../utils/cx';
import {setRefs} from '../../utils/overlay';
import {Floating, useDismiss, useHydrated, useHoverIntent, type Placement} from '../popover/float';

interface Ctx {
  open: boolean;
  show: (open: boolean, delay?: number) => void;
  openDelay: number;
  closeDelay: number;
  trigger: RefObject<HTMLElement | null>;
}
const Context = createContext<Ctx | null>(null);
/** The surrounding root's state; a part rendered outside it says so instead of failing on a null. */
function useHoverCardCtx(): Ctx {
  const c = useContext(Context);
  if (!c) throw new Error('Monoline: this HoverCard part must be rendered inside a HoverCard.');
  return c;
}

export interface HoverCardProps {
  /** Controlled open state. */
  open?: boolean | undefined;
  /** Initial open state when uncontrolled. Default false. */
  defaultOpen?: boolean | undefined;
  /** Called with the next open state. */
  onOpenChange?: ((open: boolean) => void) | undefined;
  /** Milliseconds the pointer must rest on the trigger before the card opens. Default 700. */
  openDelay?: number | undefined;
  /** Milliseconds before the card closes after the pointer leaves the trigger and the card. Default 300. */
  closeDelay?: number | undefined;
  /** The parts of the component: a trigger and its content. */
  children?: ReactNode | undefined;
}

/** The root of a card that shows extra detail when its trigger is hovered or focused. Put a `HoverCardTrigger` and `HoverCardContent` inside. */
export function HoverCard({
  open,
  defaultOpen = false,
  onOpenChange,
  openDelay = 700,
  closeDelay = 300,
  children,
}: HoverCardProps) {
  const [isOpen, setOpen] = useControllableState({value: open, defaultValue: defaultOpen, onChange: onOpenChange});
  const show = useHoverIntent(setOpen);
  const trigger = useRef<HTMLElement | null>(null);
  return <Context.Provider value={{open: isOpen, show, openDelay, closeDelay, trigger}}>{children}</Context.Provider>;
}

/** The element (usually a link) that shows the card on hover or focus; use `asChild` to render your own element. */
export const HoverCardTrigger = forwardRef<
  HTMLAnchorElement,
  AnchorHTMLAttributes<HTMLAnchorElement> & {
    /** Render your own element instead of an anchor; it receives the props and handlers. */
    asChild?: boolean | undefined;
  }
>(function HoverCardTrigger({asChild, ...rest}, ref) {
  const c = useHoverCardCtx();
  const Comp = asChild ? Slot : 'a';
  return (
    <Comp
      ref={(n: HTMLAnchorElement | null) => setRefs(n, c.trigger, ref)}
      data-state={c.open ? 'open' : 'closed'}
      {...rest}
      onPointerEnter={(e: PointerEvent) => {
        if (e.pointerType !== 'touch') c.show(true, c.openDelay);
      }}
      onPointerLeave={() => c.show(false, c.closeDelay)}
      onFocus={() => c.show(true)}
      onBlur={() => c.show(false)}
    />
  );
});

const Panel = forwardRef<HTMLDivElement, HTMLAttributes<HTMLDivElement> & Placement>(function Panel(
  {className, sideOffset = 8, align = 'start', onPointerEnter, onPointerLeave, ...rest},
  forwarded,
) {
  const c = useHoverCardCtx();
  const el = useRef<HTMLDivElement | null>(null);
  useDismiss(true, [el, c.trigger], () => c.show(false));
  return (
    <Floating
      ref={(n) => setRefs(n, el, forwarded)}
      anchor={() => c.trigger.current}
      sideOffset={sideOffset}
      align={align}
      data-state="open"
      className={cx('popover', className)}
      {...rest}
      onPointerEnter={(e) => {
        onPointerEnter?.(e);
        c.show(true);
      }}
      onPointerLeave={(e) => {
        onPointerLeave?.(e);
        c.show(false, c.closeDelay);
      }}
    />
  );
});

/** The floating card, opening 8px from the trigger and aligned to its start. Keep it supplementary: it is not reachable by touch. */
export const HoverCardContent = forwardRef<HTMLDivElement, HTMLAttributes<HTMLDivElement> & Placement>(
  function HoverCardContent(props, ref) {
    const {open} = useHoverCardCtx(),
      hydrated = useHydrated();
    return open && hydrated ? <Panel ref={ref} {...props} /> : null;
  },
);

